# b2u4 — Art, film and literature: practice sentences, 12 per lesson.
DRILLS = {
 "b2u4l1": [
  ("The director spent five years finishing this movie.", "ผู้กำกับใช้เวลาห้าปีทำหนังเรื่องนี้จนเสร็จ", "phûu-kam-kàp chái wee-laa hâa pii tham nǎng rʉ̂ang níi jon sèt"),
  ("The screenplay is based on a true story that happened in Ayutthaya.", "บทภาพยนตร์สร้างจากเรื่องจริงที่เกิดขึ้นที่อยุธยา", "bòt-phâap-phá-yon sâang jàak rʉ̂ang-jing thîi kə̀ət-khʉ̂n thîi à-yút-thá-yaa"),
  ("I didn't understand the plot very well; can you explain what happened at the end?", "ฉันไม่ค่อยเข้าใจเนื้อเรื่องเท่าไหร่ ช่วยอธิบายหน่อยได้ไหมว่าตอนจบเกิดอะไรขึ้น?", "chǎn mâi khɔ̂i khâo-jai nʉ́a-rʉ̂ang thâo-rài, chûai à-thí-baai nɔ̀i dâi mǎi wâa tɔɔn-jòp kə̀ət à-rai khʉ̂n?"),
  ("I think the funniest character in the whole movie is the main character's grandmother.", "ฉันว่าตัวละครที่ตลกที่สุดในหนังทั้งเรื่องคือคุณยายของตัวเอก", "chǎn wâa tua-lá-khɔɔn thîi tà-lòk thîi-sùt nai nǎng tháng rʉ̂ang khʉʉ khun-yaai khɔ̌ɔng tua-èek"),
  ("The young actors' natural performance made a very strong impression on me.", "การแสดงที่เป็นธรรมชาติของนักแสดงรุ่นเยาว์ทำให้ฉันประทับใจอย่างมาก", "kaan-sà-dɛɛng thîi pen-tham-má-châat khɔ̌ɔng nák-sà-dɛɛng rûn-yaao tham-hâi chǎn prà-tháp-jai yàang mâak"),
  ("The movie's music is so beautiful that I still listen to it.", "เพลงประกอบหนังเพราะมากจนตอนนี้ฉันก็ยังฟังอยู่เลย", "phleeng-prà-kɔ̀ɔp nǎng phrɔ́ mâak jon tɔɔn-níi chǎn kɔ̂ɔ yang fang yùu ləəi"),
  ("Do you prefer watching movies dubbed or with subtitles?", "คุณชอบดูหนังแบบพากย์หรือแบบมีซับมากกว่ากัน?", "khun chɔ̂ɔp duu nǎng bɛ̀ɛp phâak rʉ̌ʉ bɛ̀ɛp mii sáp mâak-kwàa kan?"),
  ("The Italian dubbing of this movie is really very bad.", "เสียงพากย์ภาษาอิตาลีของหนังเรื่องนี้แย่มากจริงๆ", "sǐang phâak phaa-sǎa ì-taa-lii khɔ̌ɔng nǎng rʉ̂ang níi yɛ̂ɛ mâak jing-jing"),
  ("This is a movie that has won awards at many international festivals but is little known to the general public.", "นี่เป็นหนังที่ได้รางวัลจากเทศกาลภาพยนตร์นานาชาติหลายแห่ง แต่คนทั่วไปไม่ค่อยรู้จัก", "nîi pen nǎng thîi dâi raang-wan jàak thêet-sà-kaan phâap-phá-yon naa-naa-châat lǎai hɛ̀ng, tɛ̀ɛ khon thûa-pai mâi khɔ̂i rúu-jàk"),
  ("The movie really dragged on; after an hour I fell asleep.", "หนังยืดยาดมาก ผ่านไปได้ชั่วโมงเดียวฉันก็หลับไปเลย", "nǎng yʉ̂ʉt-yâat mâak, phàan-pai dâi chûa-moong diao chǎn kɔ̂ɔ làp pai ləəi"),
  ("Shall we go see that director's new movie tonight?", "คืนนี้ไปดูหนังเรื่องใหม่ของผู้กำกับคนนั้นกันไหม?", "khʉʉn-níi pai duu nǎng rʉ̂ang mài khɔ̌ɔng phûu-kam-kàp khon nán kan mǎi?"),
  ("The subtitles changed so fast that I couldn't read anything in time!", "ซับเปลี่ยนเร็วมากจนฉันอ่านอะไรไม่ทันเลย!", "sáp plìan reo mâak jon chǎn àan à-rai mâi than ləəi!"),
 ],
 "b2u4l2": [
  ("I read this novel in one night; I couldn't stop.", "ฉันอ่านนิยายเล่มนี้จบในคืนเดียว วางไม่ลงเลย", "chǎn àan ní-yaai lêm níi jòp nai khʉʉn diao, waang mâi long ləəi"),
  ("Sidaoruang's stories are short, but each one has a deep meaning.", "เรื่องของศรีดาวเรืองสั้นๆ แต่ทุกเรื่องมีความหมายลึกซึ้ง", "rʉ̂ang khɔ̌ɔng sǐi-daao-rʉang sân-sân, tɛ̀ɛ thúk rʉ̂ang mii khwaam-mǎai lʉ́k-sʉ́ng"),
  ("My grandmother still knows hundreds of Sunthorn Phu's poems by heart.", "ยายของฉันยังท่องกลอนของสุนทรภู่ได้หลายร้อยบท", "yaai khɔ̌ɔng chǎn yang thɔ̂ng klɔɔn khɔ̌ɔng sǔn-thɔɔn-phûu dâi lǎai rɔ́ɔi bòt"),
  ("I'm looking for a novel whose main character is a woman doctor.", "ฉันกำลังหานิยายที่ตัวเอกเป็นหมอผู้หญิง", "chǎn kam-lang hǎa ní-yaai thîi tua-èek pen mɔ̌ɔ phûu-yǐng"),
  ("The author's style is very simple, but rich in wonderful metaphors.", "ลีลาการเขียนของผู้เขียนเรียบง่ายมาก แต่เต็มไปด้วยอุปมาอุปไมยที่งดงาม", "lii-laa-kaan-khǐan khɔ̌ɔng phûu-khǐan rîap-ngâai mâak, tɛ̀ɛ tem-pai-dûai ùp-pà-maa-ùp-pà-mai thîi ngót-ngaam"),
  ("Do you know if there is an Italian translation of Kukrit Pramoj's novel \"Four Reigns\"?", "รู้ไหมว่านิยายเรื่อง “สี่แผ่นดิน” ของคึกฤทธิ์ ปราโมช มีฉบับแปลภาษาอิตาลีหรือเปล่า?", "rúu mǎi wâa ní-yaai rʉ̂ang “sìi-phɛ̀n-din” khɔ̌ɔng khʉ́k-rít praa-môot mii chà-bàp plɛɛ phaa-sǎa ì-taa-lii rʉ̌ʉ-plào?"),
  ("After the third chapter the story gets much more interesting; be patient!", "หลังจากบทที่สามเรื่องจะสนุกขึ้นเยอะ ใจเย็นๆ นะ!", "lǎng-jàak bòt thîi sǎam rʉ̂ang jà sà-nùk khʉ̂n yə́, jai-yen-yen ná!"),
  ("The main character is a young man who left his village and went to the city.", "ตัวเอกเป็นชายหนุ่มที่ทิ้งหมู่บ้านเข้าไปอยู่ในเมือง", "tua-èek pen chaai-nùm thîi thíng mùu-bâan khâo pai yùu nai mʉang"),
  ("Why are classic works still read even after so many centuries?", "ทำไมวรรณกรรมคลาสสิกยังมีคนอ่านอยู่ แม้จะผ่านมาหลายร้อยปีแล้ว?", "tham-mai wan-ná-kam khlâat-sìk yang mii khon àan yùu, mɛ́ɛ jà phàan maa lǎai rɔ́ɔi pii lɛ́ɛo?"),
  ("Every translation loses something of the original text, and nothing can be done about it.", "การแปลทุกครั้งย่อมทำให้บางอย่างในต้นฉบับหายไป ซึ่งเป็นเรื่องที่ช่วยไม่ได้", "kaan-plɛɛ thúk khráng yɔ̂m tham-hâi baang-yàang nai tôn-chà-bàp hǎai pai, sʉ̂ng pen rʉ̂ang thîi chûai mâi dâi"),
  ("I can't remember who the author of the book you told me about yesterday is.", "ฉันนึกไม่ออกว่าหนังสือที่คุณเล่าให้ฟังเมื่อวานใครเป็นคนเขียน", "chǎn nʉ́k mâi ɔ̀ɔk wâa nǎng-sʉ̌ʉ thîi khun lâo hâi fang mʉ̂a-waan khrai pen khon khǐan"),
  ("What a beautiful metaphor! Every time, I want to read this sentence again.", "เป็นการเปรียบเทียบที่สวยมาก! อ่านประโยคนี้กี่ครั้งก็อยากอ่านอีก", "pen kaan-prìap-thîap thîi sǔai mâak! àan prà-yòok níi kìi khráng kɔ̂ɔ yàak àan ìik"),
 ],
 "b2u4l3": [
  ("Unfortunately, the open-air concert was canceled at the last minute because of heavy rain.", "น่าเสียดายที่คอนเสิร์ตกลางแจ้งถูกยกเลิกในนาทีสุดท้ายเพราะฝนตกหนัก", "nâa-sǐa-daai thîi khɔn-sə̀ət klaang-jɛ̂ɛng thùuk yók-lə̂ək nai naa-thii sùt-tháai phrɔ́ fǒn tòk nàk"),
  ("The ranat and the saw are considered the most famous traditional Thai instruments.", "ระนาดและซอถือว่าเป็นเครื่องดนตรีไทยดั้งเดิมที่มีชื่อเสียงที่สุด", "rá-nâat lɛ́ sɔɔ thʉ̌ʉ-wâa pen khrʉ̂ang-don-trii thai dâng-dəəm thîi mii-chʉ̂ʉ-sǐang thîi-sùt"),
  ("Every time, this melody reminds me of the childhood I spent in Khon Kaen.", "ทำนองนี้ทำให้ฉันนึกถึงวัยเด็กที่ใช้ชีวิตอยู่ที่ขอนแก่นทุกครั้ง", "tham-nɔɔng níi tham-hâi chǎn nʉ́k-thʉ̌ng wai-dèk thîi chái chii-wít yùu thîi khɔ̌ɔn-kɛ̀n thúk-khráng"),
  ("I hardly understand the lyrics of the song, but I really like the music.", "ฉันแทบไม่เข้าใจเนื้อเพลงเลย แต่ชอบดนตรีมาก", "chǎn thɛ̂ɛp mâi khâo-jai nʉ́a-phleeng ləəi, tɛ̀ɛ chɔ̂ɔp don-trii mâak"),
  ("The singer's performance on stage lasted more than two hours.", "การแสดงบนเวทีของนักร้องกินเวลากว่าสองชั่วโมง", "kaan-sà-dɛɛng bon wee-thii khɔ̌ɔng nák-rɔ́ɔng kin wee-laa kwàa sɔ̌ɔng chûa-moong"),
  ("When he went on stage for the first time, his hands were shaking with excitement.", "ตอนที่เขาขึ้นเวทีครั้งแรก มือของเขาสั่นด้วยความตื่นเต้น", "tɔɔn thîi kháo khʉ̂n wee-thii khráng-rɛ̂ɛk, mʉʉ khɔ̌ɔng kháo sàn dûai khwaam-tʉ̀ʉn-tên"),
  ("At the end of the concert, the audience applauded nonstop for ten minutes.", "ตอนจบคอนเสิร์ต ผู้ชมปรบมือไม่หยุดนานสิบนาที", "tɔɔn jòp khɔn-sə̀ət, phûu-chom pròp-mʉʉ mâi yùt naan sìp naa-thii"),
  ("Do you listen more to traditional music or modern music?", "คุณฟังดนตรีดั้งเดิมหรือดนตรีสมัยใหม่มากกว่ากัน?", "khun fang don-trii dâng-dəəm rʉ̌ʉ don-trii sà-mǎi-mài mâak-kwàa kan?"),
  ("The applause was so loud that the music couldn't be heard at all.", "เสียงปรบมือดังมากจนไม่ได้ยินเสียงดนตรีเลย", "sǐang pròp-mʉʉ dang mâak jon mâi dâi-yin sǐang don-trii ləəi"),
  ("Dear audience members, please turn off your phones during the performance!", "ท่านผู้ชมที่เคารพ กรุณาปิดโทรศัพท์มือถือระหว่างการแสดงด้วยครับ!", "thân phûu-chom thîi khao-róp, kà-rú-naa pìt thoo-rá-sàp mʉʉ-thʉ̌ʉ rá-wàang kaan-sà-dɛɛng dûai khráp!"),
  ("Traditional instruments can be heard even in this band's modern songs.", "แม้แต่ในเพลงสมัยใหม่ของวงนี้ก็ยังได้ยินเสียงเครื่องดนตรีพื้นเมือง", "mɛ́ɛ-tɛ̀ɛ nai phleeng sà-mǎi-mài khɔ̌ɔng wong níi kɔ̂ɔ yang dâi-yin sǐang khrʉ̂ang-don-trii phʉ́ʉn-mʉang"),
  ("What a wonderful concert it was! I will never forget this evening!", "คอนเสิร์ตสุดยอดมาก! ฉันจะไม่มีวันลืมค่ำคืนนี้เลย!", "khɔn-sə̀ət sùt-yɔ̂ɔt mâak! chǎn jà mâi mii-wan lʉʉm khâm-khʉʉn níi ləəi!"),
 ],
 "b2u4l4": [
  ("I wrote a review of the new Thai movie for the school newspaper.", "ฉันเขียนบทวิจารณ์หนังไทยเรื่องใหม่ลงหนังสือพิมพ์ของโรงเรียน", "chǎn khǐan bòt-wí-jaan nǎng thai rʉ̂ang mài long nǎng-sʉ̌ʉ-phim khɔ̌ɔng roong-rian"),
  ("My assessment is positive, even though the ending is weak.", "การประเมินของฉันเป็นไปในทางบวก ถึงแม้ตอนจบจะอ่อนไปหน่อย", "kaan-prà-məən khɔ̌ɔng chǎn pen pai nai thaang bùak, thʉ̌ng-mɛ́ɛ tɔɔn-jòp jà ɔ̀ɔn pai nɔ̀i"),
  ("Can you recommend a book to read on vacation?", "ช่วยแนะนำหนังสือไว้อ่านช่วงวันหยุดหน่อยได้ไหม?", "chûai nɛ́-nam nǎng-sʉ̌ʉ wái àan chûang wan-yùt nɔ̀i dâi mǎi?"),
  ("I don't recommend it to you: it's very long and boring.", "ฉันไม่แนะนำหรอก มันยาวและน่าเบื่อมาก", "chǎn mâi nɛ́-nam rɔ̀ɔk, man yaao lɛ́ nâa-bʉ̀a mâak"),
  ("Everyone praises this series, but I think it's overrated.", "ใครๆ ก็ชมซีรีส์เรื่องนี้ แต่ฉันว่ามันได้รับคำชมเกินจริงไปหน่อย", "khrai-khrai kɔ̂ɔ chom sii-rîi rʉ̂ang níi, tɛ̀ɛ chǎn wâa man dâi-ráp kham-chom kəən-jing pai nɔ̀i"),
  ("The director's style is very distinctive and instantly recognizable.", "สไตล์ของผู้กำกับมีเอกลักษณ์มาก ดูแล้วจำได้ทันที", "sà-tai khɔ̌ɔng phûu-kam-kàp mii èek-ká-lák mâak, duu lɛ́ɛo jam dâi than-thii"),
  ("The story is ordinary, but the actors' performance saves it.", "เนื้อเรื่องธรรมดา แต่ฝีมือการแสดงของนักแสดงช่วยพยุงเรื่องไว้ได้", "nʉ́a-rʉ̂ang tham-má-daa, tɛ̀ɛ fǐi-mʉʉ kaan-sà-dɛɛng khɔ̌ɔng nák-sà-dɛɛng chûai phá-yung rʉ̂ang wái dâi"),
  ("This is a deep book that makes you think for a long time about the meaning of human life.", "นี่เป็นหนังสือลึกซึ้งที่ทำให้เราครุ่นคิดเรื่องความหมายของชีวิตมนุษย์ไปอีกนาน", "nîi pen nǎng-sʉ̌ʉ lʉ́k-sʉ́ng thîi tham-hâi rao khrûn-khít rʉ̂ang khwaam-mǎai khɔ̌ɔng chii-wít má-nút pai ìik naan"),
  ("In the first half the pace is very slow, but then the movie comes alive.", "ครึ่งแรกจังหวะช้ามาก แต่หลังจากนั้นหนังก็เริ่มมีชีวิตชีวาขึ้น", "khrʉ̂ng rɛ̂ɛk jang-wà cháa mâak, tɛ̀ɛ lǎng-jàak-nán nǎng kɔ̂ɔ rə̂əm mii-chii-wít-chii-waa khʉ̂n"),
  ("Overall, despite its flaws, it's a movie worth the price of a ticket.", "โดยรวมแล้ว ถึงจะมีข้อเสียอยู่บ้าง แต่ก็เป็นหนังที่คุ้มค่าตั๋ว", "dooi-ruam lɛ́ɛo, thʉ̌ng jà mii khɔ̂ɔ-sǐa yùu bâang, tɛ̀ɛ kɔ̂ɔ pen nǎng thîi khúm khâa-tǔa"),
  ("What score would you give this album on a ten-point scale?", "ถ้าคะแนนเต็มสิบ คุณจะให้อัลบั้มนี้กี่คะแนน?", "thâa khá-nɛɛn tem sìp, khun jà hâi an-bâm níi kìi khá-nɛɛn?"),
  ("Don't blindly trust online reviews; many of them are fake!", "อย่าเชื่อรีวิวออนไลน์แบบหลับหูหลับตา เพราะหลายรีวิวเป็นของปลอม!", "yàa chʉ̂a rii-wiu ɔɔn-laai bɛ̀ɛp làp-hǔu-làp-taa, phrɔ́ lǎai rii-wiu pen khɔ̌ɔng-plɔɔm!"),
 ],
 "b2u4x1": [
  ("Historical novels help me better understand our country's past.", "นิยายอิงประวัติศาสตร์ช่วยให้ฉันเข้าใจอดีตของประเทศเราได้ดีขึ้น", "ní-yaai ing-prà-wàt-sàat chûai hâi chǎn khâo-jai à-dìit khɔ̌ɔng prà-thêet rao dâi dii khʉ̂n"),
  ("Every evening before bed I read a chapter of a detective novel.", "ทุกคืนก่อนนอน ฉันจะอ่านนิยายสืบสวนหนึ่งบท", "thúk khʉʉn kɔ̀ɔn nɔɔn, chǎn jà àan ní-yaai sʉ̀ʉp-sǔan nʉ̀ng bòt"),
  ("Science fiction often predicts the future better than experts do.", "นิยายวิทยาศาสตร์มักทำนายอนาคตได้แม่นยำกว่าผู้เชี่ยวชาญ", "ní-yaai wít-thá-yaa-sàat mák tham-naai à-naa-khót dâi mɛ̂n-yam kwàa phûu-chîao-chaan"),
  ("He wrote a biography of a famous twentieth-century poet.", "เขาเขียนชีวประวัติของกวีชื่อดังแห่งศตวรรษที่ยี่สิบ", "kháo khǐan chii-wá-prà-wàt khɔ̌ɔng kà-wii chʉ̂ʉ-dang hɛ̀ng sà-tà-wát thîi yîi-sìp"),
  ("In his autobiography he talks about his difficult childhood.", "ในอัตชีวประวัติ เขาเล่าถึงวัยเด็กที่ยากลำบากของตัวเอง", "nai àt-tà-chii-wá-prà-wàt, kháo lâo thʉ̌ng wai-dèk thîi yâak-lam-bàak khɔ̌ɔng tua-eeng"),
  ('The most famous folk epic of the Thai people is, without a doubt, "Khun Chang Khun Phaen".', "ไม่ต้องสงสัยเลยว่ามหากาพย์พื้นบ้านที่โด่งดังที่สุดของคนไทยคือ “ขุนช้างขุนแผน”", "mâi-tɔ̂ng-sǒng-sǎi ləəi wâa má-hǎa-kàap phʉ́ʉn-bâan thîi dòong-dang thîi-sùt khɔ̌ɔng khon-thai khʉʉ “khǔn-cháang-khǔn-phɛ̌ɛn”"),
  ("When you go to the theater, do you prefer tragedies or funny comedies?", "เวลาไปดูละครเวที คุณชอบแนวโศกนาฏกรรมหรือแนวตลกขบขันมากกว่ากัน?", "wee-laa pai duu lá-khɔɔn-wee-thii, khun chɔ̂ɔp nɛɛo sòok-kà-nâat-tà-kam rʉ̌ʉ nɛɛo tà-lòk-khòp-khǎn mâak-kwàa kan?"),
  ("This satire also shows the problems of today's society very precisely.", "งานเสียดสีชิ้นนี้ยังสะท้อนปัญหาของสังคมปัจจุบันได้อย่างตรงจุดมาก", "ngaan sìat-sǐi chín níi yang sà-thɔ́ɔn pan-hǎa khɔ̌ɔng sǎng-khom pàt-jù-ban dâi yàang trong-jùt mâak"),
  ("His first work immediately became a bestseller.", "ผลงานชิ้นแรกของเขากลายเป็นหนังสือขายดีทันที", "phǒn-ngaan chín rɛ̂ɛk khɔ̌ɔng kháo klaai-pen nǎng-sʉ̌ʉ khǎai-dii than-thii"),
  ("When you were young, did you ever keep a diary, and did you read it again later?", "ตอนเด็กๆ คุณเคยเขียนไดอารี่ไหม แล้วภายหลังได้กลับมาอ่านอีกหรือเปล่า?", "tɔɔn dèk-dèk khun khəəi khǐan dai-aa-rîi mǎi, lɛ́ɛo phaai-lǎng dâi klàp-maa àan ìik rʉ̌ʉ-plào?"),
  ("This novella isn't very long; you can read it in an hour or two.", "นิยายขนาดสั้นเรื่องนี้ไม่ยาวมาก อ่านชั่วโมงสองชั่วโมงก็จบ", "ní-yaai khà-nàat-sân rʉ̂ang níi mâi yaao mâak, àan chûa-moong sɔ̌ɔng chûa-moong kɔ̂ɔ jòp"),
  ("Which contemporary Thai author do you like the most?", "ในบรรดานักเขียนไทยร่วมสมัย คุณชอบใครมากที่สุด?", "nai ban-daa nák-khǐan thai rûam-sà-mǎi, khun chɔ̂ɔp khrai mâak thîi-sùt?"),
 ],
 "b2u4x2": [
  ("The events of the work are told from the point of view of an eight-year-old child.", "เรื่องราวในผลงานชิ้นนี้ถูกเล่าผ่านมุมมองของเด็กอายุแปดขวบ", "rʉ̂ang-raao nai phǒn-ngaan chín níi thùuk lâo phàan mum-mɔɔng khɔ̌ɔng dèk aa-yú pɛ̀ɛt khùap"),
  ("The plot is so complicated that I had to reread some chapters.", "โครงเรื่องซับซ้อนมากจนฉันต้องกลับไปอ่านบางบทใหม่", "khroong-rʉ̂ang sáp-sɔ́ɔn mâak jon chǎn tɔ̂ng klàp pai àan baang bòt mài"),
  ("Secondary characters are often more interesting than the main character.", "ตัวละครรองมักน่าสนใจกว่าตัวเอก", "tua-lá-khɔɔn rɔɔng mák nâa-sǒn-jai kwàa tua-èek"),
  ("The events of the novel take place in Chiang Mai in the fifteenth century.", "เหตุการณ์ในนิยายเกิดขึ้นที่เชียงใหม่ในศตวรรษที่สิบห้า", "hèet-kaan nai ní-yaai kə̀ət-khʉ̂n thîi chiang-mài nai sà-tà-wát thîi sìp-hâa"),
  ("In the story, the mango tree is interpreted as a symbol of family and unity.", "ในเรื่อง ต้นมะม่วงถูกตีความว่าเป็นสัญลักษณ์ของครอบครัวและความสามัคคี", "nai rʉ̂ang, tôn-má-mûang thùuk tii-khwaam wâa pen sǎn-yá-lák khɔ̌ɔng khrɔ̂ɔp-khrua lɛ́ khwaam-sǎa-mák-khii"),
  ("In your opinion, what idea did the author want to convey through this work?", "คุณคิดว่าผู้เขียนต้องการสื่อแนวคิดอะไรผ่านผลงานชิ้นนี้?", "khun khít wâa phûu-khǐan tɔ̂ng-kaan sʉ̀ʉ nɛɛo-khít à-rai phàan phǒn-ngaan chín níi?"),
  ("The flashback in the second chapter reveals a lot about the main character's childhood.", "ฉากย้อนอดีตในบทที่สองเผยให้เห็นเรื่องราววัยเด็กของตัวเอกมากมาย", "chàak yɔ́ɔn-à-dìit nai bòt thîi sɔ̌ɔng phə̌əi hâi hěn rʉ̂ang-raao wai-dèk khɔ̌ɔng tua-èek mâak-maai"),
  ("Without knowing the historical context, it's very hard to fully understand this novel.", "ถ้าไม่รู้บริบททางประวัติศาสตร์ก็ยากมากที่จะเข้าใจนิยายเรื่องนี้ได้อย่างถ่องแท้", "thâa mâi rúu bɔɔ-rí-bòt thaang prà-wàt-sàat kɔ̂ɔ yâak mâak thîi jà khâo-jai ní-yaai rʉ̂ang níi dâi yàang thɔ̀ng-thɛ́ɛ"),
  ("What an unexpected twist! The narrator is actually the main character's older brother!", "หักมุมแบบไม่คาดคิดเลย! ที่แท้ผู้เล่าเรื่องก็คือพี่ชายของตัวเอกนี่เอง!", "hàk-mum bɛ̀ɛp mâi khâat-khít ləəi! thîi-thɛ́ɛ phûu-lâo-rʉ̂ang kɔ̂ɔ khʉʉ phîi-chaai khɔ̌ɔng tua-èek nîi-eeng!"),
  ("The main character's final monologue is the most moving part of the whole work.", "บทพูดคนเดียวตอนท้ายของตัวเอกเป็นส่วนที่ซาบซึ้งที่สุดในทั้งเรื่อง", "bòt-phûut khon-diao tɔɔn tháai khɔ̌ɔng tua-èek pen sùan thîi sâap-sʉ́ng thîi-sùt nai tháng rʉ̂ang"),
  ("I don't really like open endings, because I want to know what happens in the end.", "ฉันไม่ค่อยชอบตอนจบแบบปลายเปิด เพราะอยากรู้ว่าสุดท้ายแล้วเกิดอะไรขึ้น", "chǎn mâi khɔ̂i chɔ̂ɔp tɔɔn-jòp bɛ̀ɛp plaai-pə̀ət, phrɔ́ yàak rúu wâa sùt-tháai lɛ́ɛo kə̀ət à-rai khʉ̂n"),
  ("The lively dialogues in the work speed up the pace of the story a lot and don't bore the reader.", "บทสนทนาที่มีชีวิตชีวาช่วยให้เรื่องดำเนินไปเร็วขึ้นมากและไม่ทำให้ผู้อ่านเบื่อ", "bòt-sǒn-thá-naa thîi mii-chii-wít-chii-waa chûai hâi rʉ̂ang dam-nəən pai reo khʉ̂n mâak lɛ́ mâi tham-hâi phûu-àan bʉ̀a"),
 ],
 "b2u4x3": [
  ("Each khlong stanza consists of only four lines, but expresses a deep meaning.", "โคลงแต่ละบทมีแค่สี่บาท แต่สื่อความหมายได้ลึกซึ้ง", "khloong tɛ̀ɛ-lá bòt mii khɛ̂ɛ sìi bàat, tɛ̀ɛ sʉ̀ʉ khwaam-mǎai dâi lʉ́k-sʉ́ng"),
  ("In classical Thai poetry, the rules of meter were very strict.", "ในกวีนิพนธ์ไทยโบราณ กฎฉันทลักษณ์เคร่งครัดมาก", "nai kà-wii-ní-phon thai boo-raan, kòt chǎn-thá-lák khrêng-khrát mâak"),
  ("This stanza has no rhyme, but it is very musical.", "บทนี้ไม่มีสัมผัส แต่อ่านแล้วไพเราะมาก", "bòt níi mâi mii sǎm-phàt, tɛ̀ɛ àan lɛ́ɛo phai-rɔ́ mâak"),
  ("Sunthorn Phu is considered the greatest classical Thai poet.", "สุนทรภู่ได้รับการยกย่องว่าเป็นกวีคลาสสิกที่ยิ่งใหญ่ที่สุดของไทย", "sǔn-thɔɔn-phûu dâi-ráp kaan-yók-yɔ̂ng wâa pen kà-wii khlâat-sìk thîi yîng-yài thîi-sùt khɔ̌ɔng thai"),
  ("Translating poetry is an art of its own, because it's very hard to keep the rhyme and the meter.", "การแปลบทกวีเป็นศิลปะอีกแขนงหนึ่ง เพราะรักษาสัมผัสและฉันทลักษณ์ไว้ได้ยากมาก", "kaan-plɛɛ bòt-kà-wii pen sǐn-lá-pà ìik khà-nɛ̌ɛng nʉ̀ng, phrɔ́ rák-sǎa sǎm-phàt lɛ́ chǎn-thá-lák wái dâi yâak mâak"),
  ("Some wordplay is so complex that it really can't be translated.", "การเล่นคำบางอย่างซับซ้อนจนแปลไม่ได้จริงๆ", "kaan-lên-kham baang yàang sáp-sɔ́ɔn jon plɛɛ mâi dâi jing-jing"),
  ('In the evenings, my grandfather used to recite verses from "Phra Aphai Mani" to us from memory.', "ตอนค่ำๆ คุณตามักจะท่องกลอนจากเรื่อง “พระอภัยมณี” ให้เราฟังแบบปากเปล่า", "tɔɔn khâm-khâm khun-taa mák jà thɔ̂ng klɔɔn jàak rʉ̂ang “phrá-à-phai-má-nii” hâi rao fang bɛ̀ɛp pàak-plào"),
  ("Tonight there will be a poetry reading by young poets at the library.", "คืนนี้ที่ห้องสมุดจะมีงานอ่านบทกวีของกวีรุ่นใหม่", "khʉʉn-níi thîi hɔ̂ng-sà-mùt jà mii ngaan àan bòt-kà-wii khɔ̌ɔng kà-wii rûn-mài"),
  ("Did you buy the modern poetry collection I told you about?", "คุณซื้อหนังสือรวมบทกวีสมัยใหม่ที่ฉันบอกไปหรือยัง?", "khun sʉ́ʉ nǎng-sʉ̌ʉ ruam bòt-kà-wii sà-mǎi-mài thîi chǎn bɔ̀ɔk pai rʉ̌ʉ-yang?"),
  ("In free verse, the poet follows neither rhyme nor meter.", "ในกลอนเปล่า กวีไม่ยึดทั้งสัมผัสและฉันทลักษณ์", "nai klɔɔn-plào, kà-wii mâi yʉ́t tháng sǎm-phàt lɛ́ chǎn-thá-lák"),
  ("In this poem the wind is personified: it speaks and cries.", "ในบทกวีนี้ลมถูกสมมติให้เป็นเหมือนคน คือพูดได้และร้องไห้ได้", "nai bòt-kà-wii níi lom thùuk sǒm-mút hâi pen mʉ̌an khon, khʉʉ phûut dâi lɛ́ rɔ́ɔng-hâi dâi"),
  ("Sometimes the silence between two lines says more than words.", "บางครั้งความเงียบระหว่างสองบาทก็บอกอะไรได้มากกว่าคำพูด", "baang-khráng khwaam-ngîap rá-wàang sɔ̌ɔng bàat kɔ̂ɔ bɔ̀ɔk à-rai dâi mâak-kwàa kham-phûut"),
 ],
 "b2u4x4": [
  ("The close-up shows all the fear in his eyes.", "ภาพโคลสอัพทำให้เห็นความกลัวทั้งหมดในแววตาของเขา", "phâap khlóot-àp tham-hâi hěn khwaam-klua tháng-mòt nai wɛɛo-taa khɔ̌ɔng kháo"),
  ("The movie begins with a wide long shot of snowy mountains.", "หนังเปิดเรื่องด้วยภาพมุมกว้างของภูเขาที่ปกคลุมด้วยหิมะ", "nǎng pə̀ət rʉ̂ang dûai phâap mum-kwâang khɔ̌ɔng phuu-khǎo thîi pòk-khlum dûai hì-má"),
  ("The fast editing in the last scene creates strong excitement in the viewer.", "การตัดต่อที่รวดเร็วในฉากสุดท้ายสร้างความตื่นเต้นให้ผู้ชมอย่างมาก", "kaan-tàt-tɔ̀ɔ thîi rûat-reo nai chàak sùt-tháai sâang khwaam-tʉ̀ʉn-tên hâi phûu-chom yàang mâak"),
  ("They say the screenwriter rewrote the ending of the movie three times.", "ได้ยินมาว่าคนเขียนบทเขียนตอนจบของหนังใหม่ถึงสามครั้ง", "dâi-yin maa wâa khon-khǐan-bòt khǐan tɔɔn-jòp khɔ̌ɔng nǎng mài thʉ̌ng sǎam khráng"),
  ("Thanks to the natural lighting, every shot looks just like a painting in a museum.", "เพราะใช้แสงธรรมชาติ ทุกช็อตจึงดูเหมือนภาพวาดในพิพิธภัณฑ์เลย", "phrɔ́ chái sɛ̌ɛng tham-má-châat, thúk chɔ́t jʉng duu mʉ̌an phâap-wâat nai phí-phít-thá-phan ləəi"),
  ("The costumes and the sets perfectly recreate that era.", "เครื่องแต่งกายและฉากถ่ายทอดยุคนั้นออกมาได้อย่างสมบูรณ์แบบ", "khrʉ̂ang-tɛ̀ng-kaai lɛ́ chàak thàai-thɔ̂ɔt yúk nán ɔ̀ɔk-maa dâi yàang sǒm-buun-bɛ̀ɛp"),
  ("The special effects are truly amazing, but the movie's story is very weak.", "เทคนิคพิเศษน่าทึ่งมากจริงๆ แต่เนื้อเรื่องของหนังอ่อนมาก", "thék-ník-phí-sèet nâa-thʉ̂ng mâak jing-jing, tɛ̀ɛ nʉ́a-rʉ̂ang khɔ̌ɔng nǎng ɔ̀ɔn mâak"),
  ("The audition went well: they cast me in a small role!", "การแคสติ้งผ่านไปด้วยดี เขาให้ฉันเล่นบทเล็กๆ บทหนึ่ง!", "kaan khɛ́ɛt-tîng phàan pai dûai-dii, kháo hâi chǎn lên bòt lék-lék bòt nʉ̀ng!"),
  ("In dangerous scenes, an experienced stunt double plays instead of the famous actor.", "ในฉากอันตราย สตันท์แมนที่มีประสบการณ์จะเล่นแทนนักแสดงชื่อดัง", "nai chàak an-tà-raai, sà-tan-mɛɛn thîi mii prà-sòp-kaan jà lên thɛɛn nák-sà-dɛɛng chʉ̂ʉ-dang"),
  ("Do you know which company handles the movie's distribution abroad? (formal)", "คุณทราบไหมครับว่าบริษัทไหนดูแลการจัดจำหน่ายภาพยนตร์เรื่องนี้ในต่างประเทศ?", "khun sâap mǎi khráp wâa bɔɔ-rí-sàt nǎi duu-lɛɛ kaan-jàt-jam-nàai phâap-phá-yon rʉ̂ang níi nai tàang-prà-thêet?"),
  ("Interesting: it turns out the movie's cast is made up almost entirely of amateurs.", "น่าสนใจนะ ปรากฏว่านักแสดงในหนังเกือบทั้งหมดเป็นมือสมัครเล่น", "nâa-sǒn-jai ná, praa-kòt-wâa nák-sà-dɛɛng nai nǎng kʉ̀ap tháng-mòt pen mʉʉ-sà-màk-lên"),
  ("Look how smoothly and beautifully the camera is moving in this scene!", "ดูสิ ในฉากนี้กล้องเคลื่อนไปอย่างลื่นไหลและสวยงามมาก!", "duu sì, nai chàak níi klɔ̂ng khlʉ̂an pai yàang lʉ̂ʉn-lǎi lɛ́ sǔai-ngaam mâak!"),
 ],
 "b2u4x5": [
  ("The movie's strongest point is, without a doubt, the cinematography and the lighting.", "ไม่ต้องสงสัยเลยว่าจุดเด่นที่สุดของหนังคืองานถ่ายภาพและการจัดแสง", "mâi-tɔ̂ng-sǒng-sǎi ləəi wâa jùt-dèn thîi-sùt khɔ̌ɔng nǎng khʉʉ ngaan thàai-phâap lɛ́ kaan-jàt-sɛ̌ɛng"),
  ("The weak point of the work is that the dialogues often sound artificial and lifeless.", "จุดอ่อนของผลงานชิ้นนี้คือบทสนทนามักฟังดูไม่เป็นธรรมชาติและไร้ชีวิตชีวา", "jùt-ɔ̀ɔn khɔ̌ɔng phǒn-ngaan chín níi khʉʉ bòt-sǒn-thá-naa mák fang duu mâi pen-tham-má-châat lɛ́ rái chii-wít-chii-waa"),
  ("Unfortunately, the ending of the movie was predictable from the very first scene.", "น่าเสียดายที่ตอนจบของหนังเดาได้ตั้งแต่ฉากแรกเลย", "nâa-sǐa-daai thîi tɔɔn-jòp khɔ̌ɔng nǎng dao dâi tâng-tɛ̀ɛ chàak rɛ̂ɛk ləəi"),
  ("This is a really gripping novel that you read in one sitting; you all should definitely read it!", "นี่เป็นนิยายที่สนุกมากจนต้องอ่านรวดเดียวจบ ทุกคนต้องอ่านให้ได้เลยนะ!", "nîi pen ní-yaai thîi sà-nùk mâak jon tɔ̂ng àan rûat-diao jòp, thúk-khon tɔ̂ng àan hâi dâi ləəi ná!"),
  ("The movie is suitable for the whole family, but it isn't recommended for very young children.", "หนังเรื่องนี้เหมาะกับทั้งครอบครัว แต่ไม่แนะนำสำหรับเด็กเล็ก", "nǎng rʉ̂ang níi mɔ̀ kàp tháng khrɔ̂ɔp-khrua, tɛ̀ɛ mâi nɛ́-nam sǎm-ràp dèk-lék"),
  ("Warning, I'm going to reveal the plot! If you haven't seen the series, don't read any further!", "คำเตือน ต่อไปนี้จะสปอยล์เนื้อเรื่อง! ถ้ายังไม่ได้ดูซีรีส์เรื่องนี้ก็อย่าอ่านต่อนะ!", "kham-tʉan, tɔ̀ɔ-pai-níi jà sà-pɔɔi nʉ́a-rʉ̂ang! thâa yang mâi dâi duu sii-rîi rʉ̂ang níi kɔ̂ɔ yàa àan tɔ̀ɔ ná!"),
  ("The documentary is amazing: I didn't know anything about this story.", "สารคดีเรื่องนี้น่าทึ่งมาก ฉันไม่เคยรู้เรื่องราวนี้มาก่อนเลย", "sǎa-rá-khá-dii rʉ̂ang níi nâa-thʉ̂ng mâak, chǎn mâi khəəi rúu rʉ̂ang-raao níi maa kɔ̀ɔn ləəi"),
  ("Critics consider it superficial, but audiences love it.", "นักวิจารณ์มองว่ามันตื้นเขิน แต่ผู้ชมกลับชอบมาก", "nák-wí-jaan mɔɔng wâa man tʉ̂ʉn-khə̌ən, tɛ̀ɛ phûu-chom klàp chɔ̂ɔp mâak"),
  ("His first movie was overlooked in its time, but today everyone knows it.", "หนังเรื่องแรกของเขาไม่ได้รับความสนใจในสมัยนั้น แต่ทุกวันนี้ใครๆ ก็รู้จัก", "nǎng rʉ̂ang rɛ̂ɛk khɔ̌ɔng kháo mâi dâi-ráp khwaam-sǒn-jai nai sà-mǎi nán, tɛ̀ɛ thúk-wan-níi khrai-khrai kɔ̂ɔ rúu-jàk"),
  ("My final verdict: three out of five, no more.", "คำตัดสินสุดท้ายของฉันคือสามจากห้าคะแนน ไม่เกินนี้", "kham-tàt-sǐn sùt-tháai khɔ̌ɔng chǎn khʉʉ sǎam jàak hâa khá-nɛɛn, mâi kəən níi"),
  ("In your opinion, what target audience is this series mainly aimed at? (formal)", "คุณคิดว่าซีรีส์เรื่องนี้มุ่งเน้นกลุ่มเป้าหมายไหนเป็นหลักคะ?", "khun khít wâa sii-rîi rʉ̂ang níi mûng-néen klùm-pâo-mǎai nǎi pen làk khá?"),
  ("Despite some slow scenes, my overall assessment is still positive.", "ถึงจะมีบางฉากที่ยืดยาด แต่โดยรวมแล้วฉันก็ยังให้คะแนนในทางบวก", "thʉ̌ng jà mii baang chàak thîi yʉ̂ʉt-yâat, tɛ̀ɛ dooi-ruam lɛ́ɛo chǎn kɔ̂ɔ yang hâi khá-nɛɛn nai thaang bùak"),
 ],
 "b2u4x6": [
  ("Don't be late, you all: the curtain goes up at exactly seven o'clock and the doors close!", "ทุกคนอย่ามาสายนะ ม่านจะเปิดตอนหนึ่งทุ่มตรงและประตูจะปิดทันที!", "thúk-khon yàa maa sǎai ná, mâan jà pə̀ət tɔɔn nʉ̀ng-thûm trong lɛ́ prà-tuu jà pìt than-thii!"),
  ("During the premiere, the actor forgot one of his lines, but nobody noticed.", "ระหว่างรอบปฐมทัศน์ นักแสดงลืมบทพูดไปประโยคหนึ่ง แต่ไม่มีใครสังเกต", "rá-wàang rɔ̂ɔp-pà-thǒm-mát, nák-sà-dɛɛng lʉʉm bòt-phûut pai prà-yòok nʉ̀ng, tɛ̀ɛ mâi mii khrai sǎng-kèet"),
  ("The dress rehearsal went very badly, but they say that brings good luck.", "การซ้อมใหญ่ออกมาแย่มาก แต่เขาว่ากันว่านั่นจะนำโชคดีมาให้", "kaan-sɔ́ɔm-yài ɔ̀ɔk-maa yɛ̂ɛ mâak, tɛ̀ɛ kháo wâa kan wâa nân jà nam chôok-dii maa hâi"),
  ("The play consists of three acts, with two intermissions.", "ละครเรื่องนี้มีสามองก์และมีช่วงพักสองช่วง", "lá-khɔɔn rʉ̂ang níi mii sǎam ong lɛ́ mii chûang-phák sɔ̌ɔng chûang"),
  ("This time the theater director chose a very simple staging, without sets.", "ครั้งนี้ผู้กำกับละครเวทีเลือกจัดการแสดงแบบเรียบง่ายมากโดยไม่มีฉาก", "khráng-níi phûu-kam-kàp lá-khɔɔn-wee-thii lʉ̂ak jàt kaan-sà-dɛɛng bɛ̀ɛp rîap-ngâai mâak dooi mâi mii chàak"),
  ("My cousin took part as an extra in the National Theater's new play.", "ลูกพี่ลูกน้องของฉันได้เป็นตัวประกอบในละครเรื่องใหม่ของโรงละครแห่งชาติ", "lûuk-phîi-lûuk-nɔ́ɔng khɔ̌ɔng chǎn dâi pen tua-prà-kɔ̀ɔp nai lá-khɔɔn rʉ̂ang mài khɔ̌ɔng roong-lá-khɔɔn-hɛ̀ng-châat"),
  ("We got seats not in the balcony but in the orchestra, right in the third row.", "เราได้ที่นั่งไม่ใช่ชั้นบนแต่เป็นชั้นล่าง แถวที่สามเลย", "rao dâi thîi-nâng mâi châi chán-bon tɛ̀ɛ pen chán-lâang, thɛ̌ɛo thîi sǎam ləəi"),
  ("Our theater company will go on tour around Italy next spring.", "คณะละครของเราจะไปทัวร์ทั่วอิตาลีในฤดูใบไม้ผลิปีหน้า", "khá-ná-lá-khɔɔn khɔ̌ɔng rao jà pai thua thûa ì-taa-lii nai rʉ́-duu-bai-máai-phlì pii-nâa"),
  ("The actors wore masks and didn't say a single word, because it was a pantomime.", "นักแสดงสวมหน้ากากและไม่พูดสักคำเดียว เพราะเป็นการแสดงละครใบ้", "nák-sà-dɛɛng sǔam nâa-kàak lɛ́ mâi phûut sàk kham diao, phrɔ́ pen kaan-sà-dɛɛng lá-khɔɔn-bâi"),
  ("Not everyone likes experimental theater, but it makes you think.", "ไม่ใช่ทุกคนจะชอบละครทดลอง แต่มันทำให้เราได้คิด", "mâi châi thúk-khon jà chɔ̂ɔp lá-khɔɔn thót-lɔɔng, tɛ̀ɛ man tham-hâi rao dâi khít"),
  ("Excuse me, are there still tickets left for the repeat performance on Saturday evening?", "ขอโทษครับ รอบเพิ่มเย็นวันเสาร์ยังมีตั๋วเหลืออยู่ไหมครับ?", "khɔ̌ɔ-thôot khráp, rɔ̂ɔp phə̂əm yen-wan-sǎo yang mii tǔa lʉ̌a yùu mǎi khráp?"),
  ("What an evening! The final applause lasted almost a quarter of an hour!", "ช่างเป็นค่ำคืนที่ยอดเยี่ยมจริงๆ! เสียงปรบมือตอนจบดังอยู่เกือบสิบห้านาที!", "châang pen khâm-khʉʉn thîi yɔ̂ɔt-yîam jing-jing! sǐang pròp-mʉʉ tɔɔn jòp dang yùu kʉ̀ap sìp-hâa naa-thii!"),
 ],
 "b2u4x7": [
  ("My daughter is in her second year of painting at the art academy in Bangkok.", "ลูกสาวของฉันเรียนจิตรกรรมอยู่ปีสองที่สถาบันศิลปะในกรุงเทพฯ", "lûuk-sǎao khɔ̌ɔng chǎn rian jìt-tà-kam yùu pii sɔ̌ɔng thîi sà-thǎa-ban sǐn-lá-pà nai krung-thêep"),
  ("This portrait was painted in oil on canvas in the nineteenth century.", "ภาพเหมือนนี้วาดด้วยสีน้ำมันบนผ้าใบในศตวรรษที่สิบเก้า", "phâap-mʉ̌an níi wâat dûai sǐi-nám-man bon phâa-bai nai sà-tà-wát thîi sìp-kâo"),
  ("Working with watercolor requires a very light hand and a lot of patience.", "การวาดสีน้ำต้องใช้มือที่เบามากและความอดทนสูง", "kaan wâat sǐi-náam tɔ̂ng chái mʉʉ thîi bao mâak lɛ́ khwaam-òt-thon sǔung"),
  ("In his mountain landscapes, the perspective and the composition are almost perfect.", "ในภาพทิวทัศน์ภูเขาของเขา ทัศนมิติและการจัดองค์ประกอบแทบจะสมบูรณ์แบบ", "nai phâap thiu-thát phuu-khǎo khɔ̌ɔng kháo, thát-sà-ná-mí-tì lɛ́ kaan-jàt-ong-prà-kɔ̀ɔp thɛ̂ɛp jà sǒm-buun-bɛ̀ɛp"),
  ("I prefer figurative art, but I don't understand abstract art.", "ฉันชอบศิลปะแบบเหมือนจริงมากกว่า ส่วนศิลปะนามธรรมฉันไม่เข้าใจ", "chǎn chɔ̂ɔp sǐn-lá-pà bɛ̀ɛp mʉ̌an-jing mâak-kwàa, sùan sǐn-lá-pà naam-má-tham chǎn mâi khâo-jai"),
  ("The author used light and shadow so skillfully that the faces look alive.", "ศิลปินใช้แสงเงาได้อย่างชำนาญจนใบหน้าดูมีชีวิต", "sǐn-lá-pin chái sɛ̌ɛng-ngao dâi yàang cham-naan jon bai-nâa duu mii-chii-wít"),
  ("This Friday a group exhibition of young artists opens at the art gallery downtown.", "วันศุกร์นี้นิทรรศการกลุ่มของศิลปินรุ่นใหม่จะเปิดที่หอศิลป์ในตัวเมือง", "wan-sùk níi ní-thát-sà-kaan klùm khɔ̌ɔng sǐn-lá-pin rûn-mài jà pə̀ət thîi hɔ̌ɔ-sǐn nai tua-mʉang"),
  ("An unknown collector bought this painting for a huge amount of money.", "นักสะสมนิรนามคนหนึ่งซื้อภาพวาดนี้ไปด้วยเงินจำนวนมหาศาล", "nák-sà-sǒm ní-rá-naam khon nʉ̀ng sʉ́ʉ phâap-wâat níi pai dûai ngən jam-nuan má-hǎa-sǎan"),
  ("The restoration of the ancient mural will take at least two years.", "การบูรณะจิตรกรรมฝาผนังโบราณจะใช้เวลาอย่างน้อยสองปี", "kaan-buu-rá-ná jìt-tà-kam-fǎa-phà-nǎng boo-raan jà chái wee-laa yàang-nɔ́ɔi sɔ̌ɔng pii"),
  ("Did you understand the meaning of that installation made of broken chairs?", "คุณเข้าใจความหมายของงานศิลปะจัดวางที่ทำจากเก้าอี้หักชิ้นนั้นไหม?", "khun khâo-jai khwaam-mǎai khɔ̌ɔng ngaan sǐn-lá-pà-jàt-waang thîi tham jàak kâo-îi hàk chín nán mǎi?"),
  ("Sculpture requires not only talent but also great physical strength.", "งานประติมากรรมไม่ได้ต้องการแค่พรสวรรค์ แต่ยังต้องใช้แรงกายมากด้วย", "ngaan prà-tì-maa-kam mâi dâi tɔ̂ng-kaan khɛ̂ɛ phɔɔn-sà-wǎn, tɛ̀ɛ yang tɔ̂ng chái rɛɛng kaai mâak dûai"),
  ("Take the thinnest brush for the small details; this one is very thick!", "หยิบพู่กันด้ามที่เล็กที่สุดมาใช้กับรายละเอียดเล็กๆ อันนี้ใหญ่มาก!", "yìp phûu-kan dâam thîi lék thîi-sùt maa chái kàp raai-lá-ìat lék-lék, an níi yài mâak!"),
 ],
 "b2u4x8": [
  ("Apparently the composer wrote this famous symphony when he was only twenty.", "ได้ยินว่านักประพันธ์เพลงแต่งซิมโฟนีชื่อดังนี้ตอนอายุแค่ยี่สิบปี", "dâi-yin wâa nák-prà-phan-phleeng tɛ̀ng sim-foo-nii chʉ̂ʉ-dang níi tɔɔn aa-yú khɛ̂ɛ yîi-sìp pii"),
  ("The conductor stopped the rehearsal three times and gave comments to the string section.", "วาทยกรหยุดการซ้อมสามครั้งเพื่อให้คำแนะนำกับกลุ่มเครื่องสาย", "waa-thá-yá-kɔɔn yùt kaan-sɔ́ɔm sǎam khráng phʉ̂a hâi kham-nɛ́-nam kàp klùm khrʉ̂ang-sǎai"),
  ("Can you read music, or do you only play melodies by ear?", "คุณอ่านโน้ตเพลงได้ไหม หรือฟังแล้วเล่นตามอย่างเดียว?", "khun àan nóot-phleeng dâi mǎi, rʉ̌ʉ fang lɛ́ɛo lên taam yàang-diao?"),
  ("In traditional Thai music, unlike Western classical music, melody is more important than harmony.", "ในดนตรีไทยเดิม ต่างจากดนตรีคลาสสิกตะวันตก ทำนองสำคัญกว่าเสียงประสาน", "nai don-trii thai dəəm, tàang-jàak don-trii khlâat-sìk tà-wan-tòk, tham-nɔɔng sǎm-khan kwàa sǐang-prà-sǎan"),
  ("He's a true virtuoso on the chakhe; you have to hear him play live!", "เขาเป็นยอดฝีมือด้านการเล่นจะเข้ตัวจริง ต้องไปฟังเขาเล่นสดให้ได้!", "kháo pen yɔ̂ɔt-fǐi-mʉʉ dâan kaan lên jà-khêe tua-jing, tɔ̂ng pai fang kháo lên sòt hâi dâi!"),
  ("The khaen and the khlui are the most famous wind instruments in Thai folk music.", "แคนและขลุ่ยเป็นเครื่องเป่าที่มีชื่อเสียงที่สุดในดนตรีพื้นบ้านไทย", "khɛɛn lɛ́ khlùi pen khrʉ̂ang-pào thîi mii-chʉ̂ʉ-sǐang thîi-sùt nai don-trii phʉ́ʉn-bâan thai"),
  ("His interpretation of Chopin's works is very original and personal.", "การตีความผลงานของโชแปงในแบบของเขาแปลกใหม่และเป็นตัวของตัวเองมาก", "kaan tii-khwaam phǒn-ngaan khɔ̌ɔng choo-pɛɛng nai bɛ̀ɛp khɔ̌ɔng kháo plɛ̀ɛk-mài lɛ́ pen tua-khɔ̌ɔng-tua-eeng mâak"),
  ("The band recorded the new album in the studio in just one week.", "วงอัดอัลบั้มใหม่ในสตูดิโอเสร็จภายในสัปดาห์เดียว", "wong àt an-bâm mài nai sà-tuu-di-oo sèt phaai-nai sàp-daa diao"),
  ("Artists earn very little from music streaming services.", "ศิลปินได้เงินน้อยมากจากบริการสตรีมมิ่งเพลง", "sǐn-lá-pin dâi ngən nɔ́ɔi mâak jàak bɔɔ-rí-kaan sà-triim-mîng phleeng"),
  ("Do you know who owns the copyright to this song now?", "คุณรู้ไหมว่าตอนนี้ใครเป็นเจ้าของลิขสิทธิ์เพลงนี้?", "khun rúu mǎi wâa tɔɔn-níi khrai pen jâo-khɔ̌ɔng lík-khà-sìt phleeng níi?"),
  ("The acoustics in this hall are very bad: you can't hear anything from the back rows.", "อะคูสติกของห้องโถงนี้แย่มาก นั่งแถวหลังไม่ได้ยินอะไรเลย", "à-khuu-sà-tìk khɔ̌ɔng hɔ̂ng-thǒong níi yɛ̂ɛ mâak, nâng thɛ̌ɛo lǎng mâi dâi-yin à-rai ləəi"),
  ("Come on, let's play a tune from our folk music repertoire tonight!", "มาเถอะ คืนนี้มาเล่นเพลงพื้นบ้านสักเพลงจากรายการเพลงของเรากัน!", "maa thə̀, khʉʉn-níi maa lên phleeng phʉ́ʉn-bâan sàk phleeng jàak raai-kaan phleeng khɔ̌ɔng rao kan!"),
 ],
 "b2u4x9": [
  ("This publisher has already rejected my manuscript for the third time.", "สำนักพิมพ์นี้ปฏิเสธต้นฉบับของฉันเป็นครั้งที่สามแล้ว", "sǎm-nák-phim níi pà-tì-sèet tôn-chà-bàp khɔ̌ɔng chǎn pen khráng thîi sǎam lɛ́ɛo"),
  ("The first print run was only a thousand copies.", "การพิมพ์ครั้งแรกมีแค่หนึ่งพันเล่ม", "kaan-phim khráng rɛ̂ɛk mii khɛ̂ɛ nʉ̀ng phan lêm"),
  ("An Italian publisher bought the translation rights to this Thai novel.", "สำนักพิมพ์อิตาลีแห่งหนึ่งซื้อลิขสิทธิ์การแปลนิยายไทยเรื่องนี้", "sǎm-nák-phim ì-taa-lii hɛ̀ng nʉ̀ng sʉ́ʉ lík-khà-sìt kaan-plɛɛ ní-yaai thai rʉ̂ang níi"),
  ("Without a literary agent, it's very hard to get a book published abroad.", "ถ้าไม่มีตัวแทนวรรณกรรมก็ยากมากที่จะได้ตีพิมพ์หนังสือในต่างประเทศ", "thâa mâi mii tua-thɛɛn wan-ná-kam kɔ̂ɔ yâak mâak thîi jà dâi tii-phim nǎng-sʉ̌ʉ nai tàang-prà-thêet"),
  ("The author first gets an advance, and then a small percentage on each copy.", "นักเขียนจะได้เงินล่วงหน้าก่อน แล้วจึงได้ส่วนแบ่งเล็กน้อยจากทุกเล่มที่ขายได้", "nák-khǐan jà dâi ngən-lûang-nâa kɔ̀ɔn, lɛ́ɛo jʉng dâi sùan-bɛ̀ng lék-nɔ́ɔi jàak thúk lêm thîi khǎai dâi"),
  ("This year, for the first time, there will also be a Thai booth at the Turin book fair.", "ปีนี้งานหนังสือที่ตูรินจะมีบูธของไทยด้วยเป็นครั้งแรก", "pii níi ngaan nǎng-sʉ̌ʉ thîi tuu-rin jà mii bûut khɔ̌ɔng thai dûai pen khráng-rɛ̂ɛk"),
  ("For this book, word of mouth was more useful than any advertising.", "สำหรับหนังสือเล่มนี้ การบอกต่อปากต่อปากได้ผลดีกว่าโฆษณาใดๆ", "sǎm-ràp nǎng-sʉ̌ʉ lêm níi, kaan-bɔ̀ɔk-tɔ̀ɔ pàak-tɔ̀ɔ-pàak dâi-phǒn dii kwàa khôo-sà-naa dai-dai"),
  ("This is a movie not for a mass audience but for a niche audience.", "นี่เป็นหนังที่ไม่ได้ทำมาสำหรับคนหมู่มาก แต่สำหรับคนดูกลุ่มเฉพาะ", "nîi pen nǎng thîi mâi dâi tham maa sǎm-ràp khon mùu-mâak, tɛ̀ɛ sǎm-ràp khon duu klùm chà-phɔ́"),
  ("The first weekend's box office was even higher than everyone expected.", "รายได้ในสุดสัปดาห์แรกสูงกว่าที่ทุกคนคาดไว้เสียอีก", "raai-dâi nai sùt-sàp-daa rɛ̂ɛk sǔung kwàa thîi thúk-khon khâat wái sǐa-ìik"),
  ("It is believed that streaming platforms are radically changing the whole culture industry.", "เชื่อกันว่าแพลตฟอร์มสตรีมมิ่งกำลังเปลี่ยนแปลงอุตสาหกรรมวัฒนธรรมทั้งหมดอย่างถอนรากถอนโคน", "chʉ̂a kan wâa phlɛ̂ɛt-fɔɔm sà-triim-mîng kam-lang plìan-plɛɛng ùt-sǎa-hà-kam wát-thá-ná-tham tháng-mòt yàang thɔ̌ɔn-râak-thɔ̌ɔn-khoon"),
  ("Because of piracy, thousands of people who work in the film industry suffer losses.", "เพราะการละเมิดลิขสิทธิ์ คนหลายพันคนที่ทำงานในวงการภาพยนตร์ต้องเสียหาย", "phrɔ́ kaan-lá-mə̂ət-lík-khà-sìt, khon lǎai phan khon thîi tham-ngaan nai wong-kaan phâap-phá-yon tɔ̂ng sǐa-hǎai"),
  ("Do you know which companies sponsored this year's film festival? (formal)", "คุณทราบไหมคะว่าเทศกาลภาพยนตร์ปีนี้มีบริษัทไหนเป็นสปอนเซอร์บ้าง?", "khun sâap mǎi khá wâa thêet-sà-kaan phâap-phá-yon pii níi mii bɔɔ-rí-sàt nǎi pen sà-pɔn-sə̂ə bâang?"),
 ],
 "b2u4x10": [
  ("There's no point arguing about personal taste; everyone has their own opinion.", "ไม่มีประโยชน์ที่จะเถียงกันเรื่องรสนิยมส่วนตัว ทุกคนมีความเห็นของตัวเอง", "mâi mii prà-yòot thîi jà thǐang kan rʉ̂ang rót-ní-yom sùan-tua, thúk-khon mii khwaam-hěn khɔ̌ɔng tua-eeng"),
  ("I think these gold-colored figurines are a clear example of bad taste.", "ฉันว่ารูปปั้นสีทองพวกนี้เป็นตัวอย่างที่ชัดเจนของความไร้รสนิยม", "chǎn wâa rûup-pân sǐi-thɔɔng phûak níi pen tua-yàang thîi chát-jeen khɔ̌ɔng khwaam rái-rót-ní-yom"),
  ("The representatives of the avant-garde boldly broke with nineteenth-century traditions.", "ศิลปินแนวอาวองการ์ดกล้าฉีกขนบของศตวรรษที่สิบเก้า", "sǐn-lá-pin nɛɛo aa-wɔɔng-kaat klâa chìik khà-nòp khɔ̌ɔng sà-tà-wát thîi sìp-kâo"),
  ("In his style you can feel the strong influence of the classical Indian poets.", "ในสำนวนของเขาสัมผัสได้ถึงอิทธิพลอย่างมากของกวีอินเดียยุคคลาสสิก", "nai sǎm-nuan khɔ̌ɔng kháo sǎm-phàt dâi thʉ̌ng ìt-thí-phon yàang mâak khɔ̌ɔng kà-wii in-dia yúk khlâat-sìk"),
  ("This scene was created as a tribute to a famous movie from the sixties.", "ฉากนี้สร้างขึ้นเพื่อคารวะหนังชื่อดังยุคหกศูนย์", "chàak níi sâang khʉ̂n phʉ̂a khaa-rá-wá nǎng chʉ̂ʉ-dang yúk hòk-sǔun"),
  ("The line between imitation and plagiarism is sometimes very thin.", "เส้นแบ่งระหว่างการเลียนแบบกับการลอกเลียนผลงานบางครั้งก็บางมาก", "sên-bɛ̀ng rá-wàang kaan-lian-bɛ̀ɛp kàp kaan-lɔ̂ɔk-lian phǒn-ngaan baang-khráng kɔ̂ɔ baang mâak"),
  ("The exhibition caused a scandal, but the number of visitors also rose sharply.", "นิทรรศการก่อให้เกิดเรื่องอื้อฉาว แต่จำนวนผู้เข้าชมก็พุ่งสูงขึ้นด้วย", "ní-thát-sà-kaan kɔ̀ɔ hâi kə̀ət rʉ̂ang-ʉ̂ʉ-chǎao, tɛ̀ɛ jam-nuan phûu-khâo-chom kɔ̂ɔ phûng sǔung khʉ̂n dûai"),
  ("In your opinion, should artistic freedom have limits or not? (formal)", "คุณคิดว่าเสรีภาพทางศิลปะควรมีขอบเขตหรือไม่ครับ?", "khun khít wâa sěe-rii-phâap thaang sǐn-lá-pà khuan mii khɔ̀ɔp-khèet rʉ̌ʉ mâi khráp?"),
  ("I think every interpretation of a work of art is partly subjective.", "ฉันคิดว่าการตีความงานศิลปะทุกแบบล้วนมีความเป็นอัตวิสัยอยู่บ้าง", "chǎn khít wâa kaan-tii-khwaam ngaan-sǐn-lá-pà thúk bɛ̀ɛp lúan mii khwaam pen àt-tà-wí-sǎi yùu bâang"),
  ("This woman writer was rediscovered after fifty years of oblivion.", "นักเขียนหญิงคนนี้ถูกค้นพบอีกครั้งหลังจากถูกลืมไปห้าสิบปี", "nák-khǐan yǐng khon níi thùuk khón-phóp ìik-khráng lǎng-jàak thùuk lʉʉm pai hâa-sìp pii"),
  ("This time the critics all agree: the movie is a true masterpiece!", "คราวนี้นักวิจารณ์เห็นตรงกันหมด หนังเรื่องนี้เป็นผลงานชิ้นเอกตัวจริง!", "khraao-níi nák-wí-jaan hěn trong-kan mòt, nǎng rʉ̂ang níi pen phǒn-ngaan-chín-èek tua-jing!"),
  ("Why do some works become fashionable and then get forgotten quickly?", "ทำไมผลงานบางชิ้นถึงฮิตขึ้นมาแล้วก็ถูกลืมไปอย่างรวดเร็ว?", "tham-mai phǒn-ngaan baang chín thʉ̌ng hít khʉ̂n-maa lɛ́ɛo kɔ̂ɔ thùuk lʉʉm pai yàang rûat-reo?"),
 ],
}
